Firstly, we decompose the integral domain $Y_f$ into two parts (see Figure $\ref{subfig_2}$): $(Y_f)_{\rho}$ and $Y_f\setminus(Y_f)_{\rho}$, where $(Y_f)_{\rho}:=\{y\in Y_f:\text{dist}(y,\partial Y_s)\geq 2\rho\}$ for the parameter $\rho>0$, which will be fixed later. In this respect, the desired estimate $\eqref{pri:3.6}$ is reduced to showing: (For the ease of the statement, we omit the subscript of $W_j$ in the proof.)
\begin{equation}\label{f:3.9}
\bigg(\int_{Y_f}|\nabla W(\cdot,t)|^2\bigg)^{1/2}
\lesssim
\bigg(\int_{Y_f\setminus(Y_f)_{\rho}}|\nabla W(\cdot,t)|^2\bigg)^{1/2}
+\bigg(\int_{(Y_f)_{\rho}}|\nabla W(\cdot,t)|^2\bigg)^{1/2}=:I_1+I_2.
\end{equation}
The easier term is $I_1$, and by using
H\"older's inequality and the semigroup estimates (see e.g.
\cite[pp.82]{Tsai18}) in the order, we obtain
\begin{equation}\label{pde2.5}
I_1\lesssim \rho^{\frac{1}{2}-\frac{1}{p}}
\bigg(\int_{Y_f}|\nabla W(\cdot,t)|^p \bigg)^{1/p}
\lesssim \rho^{\frac{1}{2}-\frac{1}{p}}
t^{-\frac{1}{2}}.
\end{equation}

We now turn to the second term $I_2$, and start from giving
a family of cut-off functions, denoted by $\{\chi_i\}$, which
satisfy that
$\chi_{i}(y):=\chi_0(y+y_i)$, and $(Y_f)_{\rho}\subset\bigcup_{i}B(y_i,\rho)\subset
(Y_f)_{\frac{1}{2}\rho}$.
We assume that
\begin{itemize}
  \item $\chi_0\in C_{per}^1(Y)$ is a cut-off function;
  \item $\chi_0=1$ on $B(0,\rho/2)$ and supp$(\chi_0)\subset B(0,\rho)$  with $|\nabla\chi_0|\lesssim \frac{1}{\rho};$
  \item For any point in the region $(Y_f)_\rho$, it is covered by, at most, five elements of the covering family $\{B(y_i,\rho)\}$.
\end{itemize}
From the assumptions on $\{\chi_i\}$, it follows that  $\text{dist}\big(\partial Y_s,\text{supp}(\chi_i)\big)\geq \rho$.
Moreover, we define a family of indicator functions associated with
$\{\chi_i\}$ as follows:
\begin{equation*}
\tilde{\chi_i}=1 ~\text{in}~ B(y_i,\rho) \quad \text{and}\quad \tilde{\chi_i}=0 ~\text{outside}~ B(y_i,\rho).
\end{equation*}
Therefore, the second term in the right-hand side of $\eqref{f:3.9}$
can be estimated by
\begin{equation*}
I_2\leq \bigg(\sum_{i}\int_{Y_f}\chi_i^2|\nabla W(\cdot,t)|^2\bigg)^{1/2},
\end{equation*}
while we claim that: for each $i$ and any $t>0$, there hold
\begin{subequations}
\begin{align}
&\int_{Y_f}\chi_i^2|\nabla W(\cdot,t)|^2 \lesssim \int_{Y_f}\chi_i^2|\nabla\times W(\cdot,t)|^2+\frac{1}{\rho^2}\int_{Y_f}
  \tilde{\chi_i}|W(\cdot,t)|^2; \label{f:3.10a}\\
&\int_{Y_f}\chi_i^2|\nabla\times W(\cdot,t)|^2 \lesssim
\frac{1}{\rho^2}\int_{0}^{T}\int_{Y_f}
\tilde{\chi_i}|\nabla W|^2.
\label{f:3.10b}
\end{align}
\end{subequations}


Admitting the claims $\eqref{f:3.10a}$, $\eqref{f:3.10b}$ for a moment, and combining them,  we will get
\begin{equation}\label{pde2.3}
\int_{Y_f}\chi_i^2|\nabla W(\cdot,t)|^2dy\lesssim
\frac{1}{\rho^2}\bigg\{\int_{0}^{T}\int_{Y_f}
\tilde{\chi_i}|\nabla W|^2+
\sup_{0\leq t\leq T}\int_{Y_f}
  \tilde{\chi_i}|W(\cdot,t)|^2\bigg\}.
\end{equation}
In view of the assumptions on $\chi_i$ and the above estimate \eqref{pde2.3}, we obtain that
\begin{equation}\label{pde2.4}
 \begin{aligned}
 I_2&\leq\bigg(\sum_i\int_{Y_f}\chi_i^2|\nabla W(\cdot,t)|^2\bigg)^{1/2}\\
 &\lesssim \frac{1}{\rho}\bigg(
 \int_{0}^{T}\int_{Y_f}|\nabla W|^2+\sup_{0\leq t\leq T}\int_{Y_f}
 |W(\cdot,t)|^2 \bigg)^{1/2}\lesssim^{\eqref{pde2.14}} \frac{1}{\rho}.
 \end{aligned}
\end{equation}
As a result, plugging \eqref{pde2.5} and $\eqref{pde2.4}$ back into $\eqref{f:3.9}$, and then taking $\rho=t^{\frac{p}{3p-2}}$ (which
requires $t$ to be small), one can acquire
\begin{equation*}
\begin{aligned}
\bigg(\int_{Y_f}|\nabla W(\cdot,t)|^2\bigg)^{1/2}
\lesssim \rho^{\frac{1}{2}-\frac{1}{p}}t^{-\frac{1}{2}}
+\rho^{-1}
\lesssim t^{-\frac{p}{3p-2}},
\end{aligned}
\end{equation*}
which is the desired estimate $\eqref{pri:3.6}$.


We plan to use two steps to complete the whole proof, which is originally inspired by \cite{Jin13}.


