\begin{equation*}
\begin{aligned}
\int_{Y_f}\partial_t W
\cdot\nabla\times(\chi_i^2\nabla\times W)
&\overset{\eqref{k-8}}{=}-\int_{Y_f}\nabla\cdot[\partial_t W\times(\chi_i^2\nabla\times W)]
+\int_{Y_f}(\nabla\times\partial_t W)\cdot
(\chi_i^2\nabla\times W) \\
&=-\int_{\partial Y_f}\vec{n}\cdot[\partial_t W\times(\chi_i^2\nabla\times W)]
+\int_{Y_f}(\nabla\times\partial_t W)\cdot
(\chi_i^2\nabla\times W) \\
&=\frac{1}{2}\frac{d}{dt}\int_{Y_f}
\chi_i^2|\nabla\times W|^2,
\end{aligned}
\end{equation*}
where we merely take 
$\vec{a}=\partial_t W$ and $\vec{b}= \chi_i^2\nabla\times W$. This together with \eqref{pde2.6} leads to
\begin{equation}\label{k-7}
\begin{aligned}
0&=\frac{1}{2}\frac{d}{dt}\int_{Y_f}
\chi_i^2|\nabla\times W|^2
-\int_{Y_f}\Delta W\cdot\nabla\times(\chi_i^2\nabla\times W)\\
&=\frac{1}{2}\frac{d}{dt}\int_{Y_f}
\chi_i^2|\nabla\times W|^2+\int_{Y_f}\chi_i^2|\Delta W|^2-
\int_{Y_f}\Delta W\cdot\nabla\chi_i^2\times(\nabla\times W),
\end{aligned}
\end{equation}
where the second equality is due to the following computation:
\begin{equation*}
\begin{aligned}
&\nabla\times (\chi_i^2\nabla\times W)=\nabla\chi^2_i\times(\nabla\times W)+\chi_i^2\nabla\times\nabla\times W\\
&\nabla\times\nabla\times W=-\Delta W+\nabla(\nabla\cdot W)=-\Delta W.
\end{aligned}
\end{equation*}

Rewriting the above equality $\eqref{k-7}$, there holds
\begin{equation}\label{pde2.8}
\begin{aligned}
\frac{1}{2}\frac{d}{dt}\int_{Y_f}
\chi_i^2|\nabla\times W|^2+\int_{Y_f}\chi_i^2|\Delta W|^2
&=\int_{Y_f}\Delta W\cdot\nabla\chi_i^2\times(\nabla\times W)\\
&\leq 2\int_{Y_f}|\chi_i||\Delta W||\nabla \chi_i||\nabla\times W|.
\end{aligned}
\end{equation}
(Note that the repeated index $i$ does not represent a sum throughout the proofs of Lemmas $\ref{lemma3.3}$, $\ref{lemma2.2}$.)
Applying Young's inequality to the right-hand side of $\eqref{pde2.8}$, it is not hard to see that
\begin{equation*}
\frac{1}{2}\frac{d}{dt}\int_{Y_f}
\chi_i^2|\nabla\times W|^2+\int_{Y_f}\chi_i^2|\Delta W|^2
\lesssim
\int_{Y_f}|\nabla\chi_i|^2|\nabla\times W|^2,
\end{equation*}
and for any $t>0$ we consequently derive that
\begin{equation*}
\begin{aligned}
\int_{Y_f}\chi_i^2|\nabla\times W(\cdot,t)|^2
\lesssim\int_{0}^{T}\int_{Y_f}|\nabla\chi_i|^2|\nabla W|^2+\int_{Y_f}\chi_i^2|\nabla\times W(\cdot,0)|^2
\lesssim\frac{1}{\rho^2}\int_{0}^{T}\int_{Y_f}
\tilde{\chi_i}|\nabla W|^2,
\end{aligned}
\end{equation*}
which gives the claim $\eqref{f:3.10b}$.


\textbf{Step 2.} We turn to study the claim $\eqref{f:3.10a}$.
Recalling the formula $\nabla\times(\chi_i^2\nabla\times W)=\nabla\chi^2_i\times(\nabla\times W)-\chi_i^2\Delta W$ in $Y_f$, it leads us to the following integral equality
\begin{equation}\label{pde2.9}
-\int_{Y_f}\chi_i^2\Delta W\cdot W =\int_{Y_f}[\nabla\times(\chi_i^2\nabla\times W)]\cdot W -2\int_{Y_f}\chi_i(\nabla\chi_i\times\nabla\times W)\cdot W.
\end{equation}
Integrating by parts, the left-hand side of \eqref{pde2.9} is equal to
\begin{equation*}
\int_{Y_f}\chi_i^2|\nabla W|^2+2\int_{Y_f}\chi_i\nabla W:\nabla\chi_i\otimes W,
\end{equation*}
and moving the second term above to the right-hand side of \eqref{pde2.9}
we then derive that
\begin{equation}\label{pde2.10}
\int_{Y_f}\chi_i^2|\nabla W|^2 \lesssim
\int_{Y_f}|\chi_i||\nabla W||\nabla\chi_i||W|+
\Big|\int_{Y_f}\nabla\times(\chi_i^2\nabla\times W)\cdot W\Big|.
\end{equation}
Continue the computation as follows:
\begin{equation*}
\begin{aligned}
\int_{Y_f} \nabla\times(\chi_i^2\nabla\times W)
&\cdot W
\overset{\eqref{k-8}}{=}\int_{Y_f}\nabla\cdot[(\chi_i^2\nabla\times W)\times W]
+\int_{Y_f}
(\chi_i^2\nabla\times W)\cdot (\nabla\times W)\\
&=\int_{\partial Y_f}\vec{n}\cdot[(\chi_i^2\nabla\times W)\times W]
+\int_{Y_f}
(\chi_i^2\nabla\times W)\cdot (\nabla\times W)
=\int_{Y_f}
\chi_i^2|\nabla\times W|^2.
\end{aligned}
\end{equation*}
Inserting the above equality back into \eqref{pde2.10} and using
Young's inequality again, there holds
\begin{equation*}
\int_{Y_f}\chi_i^2|\nabla W|^2\leq
\theta\int_{Y_f}\chi_i^2|\nabla W|^2 +C_{\theta}\int_{Y_f}|\nabla\chi_i|^2|W|^2
+\int_{Y_f}\chi_i^2|\nabla\times W|^2,
\qquad \theta\in(0,1),
\end{equation*}
which immediately implies the stated result $\eqref{f:3.10a}$.
We have completed all the proof.

