\label{lemma2.2}
Let $d\geq 2$ and $p\geq 2$ be sufficiently large, and $\gamma:=\frac{p(19p-14)}{(3p-2)(7p-2)}$.
Suppose that $(W_j,\pi_j)$ is a weak solution of \eqref{pde2.1} with $j=1,\cdots,d$.
Then, for any $r\in(1,\infty)$,
there exists a constant $q\in(1,\infty)$, such that
$\lambda:=\frac{2(q-r)}{r(q-2)}$ satisfying $0\leq\lambda\leq 1$,
and there holds the decay estimate\textsuperscript{\ref{footnote1}}
\begin{equation}\label{pri:3.7}
\|\partial_t W_j(\cdot,t)\|_{L^r(Y_f)}\lesssim t^{-1+\lambda(1-\gamma)}

\end{equation}
for any $t>0$, where the multiplicative constant depends on $d,p,q$, and the character of $Y_f$.

In general, we adopt a similar strategy and notation as presented in Lemma \ref{lemma3.3}, with the additional use of an interpolation argument. The entire proof is structured into four steps.

\textbf{Step 1.} \emph{One step reduction.}
The main idea is that we firstly improve the decay estimate in
$L^2$-spatial norm, and then appeal to the interpolation argument
to get a weaker improvement in terms of $L^r$-spatial norms with $r\not= 2$. Thus,
the key step is to establish the following estimate: (Here we omit the subscript of $W_j$ throughout the proof.)
\begin{equation}\label{f:3.11}
\bigg(\int_{Y_f}dy|\Delta W(y,t)|^2\bigg)^{1/2}\lesssim
t^{-\gamma}
\end{equation}
for any $t>0$. Admitting the above estimate for a while, we introduce
the infinitesimal generator $\mathcal{A}:=P(-\Delta)$, where the operator $P$ is known as the Helmholtz projection, and then it follows from the boundedness of $P$ and $\eqref{f:3.11}$ that
\begin{equation*}
\|\mathcal{A}W(\cdot,t)\|_{L^2(Y_f)}=
\|P(-\Delta)W(\cdot,t)\|_{L^2(Y_f)}\leq
\|\Delta W(\cdot,t)\|_{L^2(Y_f)}\lesssim
t^{-\gamma}.
\end{equation*}
Recalling Stokes semigroup estimates (see e.g. \cite[pp.81]{Tsai18}):
for $1<q<\infty$, we have
\begin{equation*}
\|\mathcal{A} W(\cdot,t)\|_{L^q(Y_f)}\lesssim t^{-1}.
\end{equation*}
Then, by preferring a suitable $q\in(1,\infty)$ such that
$q<r\leq 2$ or $2\leq r<q$, one can employ the interpolation inequality to get that
\begin{equation*}
\begin{aligned}
\|\mathcal{A}W(\cdot,t)\|_{L^r(Y_f)}&\leq
\|\mathcal{A}W(\cdot,t)\|^{\lambda}_{L^2(Y_f)}
\|\mathcal{A}W(\cdot,t)\|^{1-\lambda}_{L^q(Y_f)}\\
&\lesssim t^{-1+\lambda(1-\gamma)},
\end{aligned}
\end{equation*}
where $\lambda:=\frac{2(q-r)}{r(q-2)}$. Using the
representation of the solution of \eqref{pde2.1} by the semigroup theory, we have $\partial_t W = \mathcal{A} W$ in
$Y_f\times (0,\infty)$, which implies
the stated estimate $\eqref{pri:3.7}$.


\textbf{Step 2.} \emph{A further reduction}.
The remainder part of the proof is devoted to establishing
the crucial estimate $\eqref{f:3.11}$ from two important ingredients.  Introducing the parameter $\rho>0$, we decompose the following integral into two parts: the inner part and the near-boundary part, i.e.,
\begin{equation}\label{pde2.24}
\bigg(
\int_{Y_f}|\Delta W(\cdot,t)|^2
\bigg)^{1/2}\leq
\bigg(
\int_{(Y_f)_{\rho}}|\Delta W(\cdot,t)|^2
\bigg)^{1/2}+
\bigg(
\int_{Y_f\setminus(Y_f)_{\rho}}|\Delta W(\cdot,t)|^2
\bigg)^{1/2}.
\end{equation}

Let $p\geq 2$, and we claim that there hold
\begin{subequations}\label{}
\begin{align}
 \bigg(
\int_{(Y_f)_{\rho}}|\nabla^2W(\cdot,t)|^2
\bigg)^{1/2}&\lesssim \rho^{-3}t^{-\frac{p}{3p-2}};\label{pde2.25}\\
 \bigg(
\int_{Y_f\setminus(Y_f)_{\rho}}|\Delta W(\cdot,t)|^2
\bigg)^{1/2}
&\lesssim \rho^{\frac{1}{2}-\frac{1}{p}}t^{-1}. \label{pde2.26}
\end{align}
\end{subequations}

Admitting the above two estimates temporarily,
we can proceed with our analysis. Inserting \eqref{pde2.25} and \eqref{pde2.26} back into \eqref{pde2.24}, we have
\begin{equation*}
\bigg(\int_{Y_f}|\Delta W(\cdot,t)|^2\bigg)^{1/2}\lesssim \rho^{-3}t^{\frac{-p}{3p-2}}+
\rho^{\frac{1}{2}-\frac{1}{p}}t^{-1},
\end{equation*}
and minimizing the right-side above by taking $\rho>0$ such that $\rho^{-3}t^{\frac{-p}{3p-2}}=
\rho^{\frac{1}{2}-\frac{1}{p}}t^{-1}$, there holds
\begin{equation*}
\bigg(\int_{Y_f}|\Delta W(\cdot,t)|^2\bigg)^{1/2}\lesssim
t^{\frac{-p(19p-14)}{(3p-2)(7p-2)}},
\end{equation*}
which gives us the core estimate $\eqref{f:3.11}$ by setting
$\gamma:=\frac{p(19p-14)}{(3p-2)(7p-2)}$.



\textbf{Step 3.} Show the estimate $\eqref{pde2.25}$.
We start from showing
\begin{equation}\label{pde2.31}
\int_{Y_f}\chi_i^2|\nabla^2 W(\cdot,t)|^2\lesssim
\|\nabla\chi_i\|^2_{L^{\infty}(Y)}\bigg\{
\int_{0}^{T}\int_{Y_f}\tilde{\chi_i}|\nabla^2 W|^2+\int_{Y_f}\tilde{\chi_i}|\nabla W(\cdot,t)|^2
\bigg\}.
\end{equation}
To see this, it is known that
$\partial_k W$ with $k=1,\cdots,d$ satisfies the equations in
$Y_f\times (0,T]$ as the same as $W$ does, and therefore it follows
from the estimate \eqref{pde2.3} that
\begin{equation*}
\int_{Y_f}\chi_i^2|\nabla \partial_k W(\cdot,t)|^2\lesssim
\|\nabla\chi_i\|^2_{L^{\infty}(Y)}\bigg\{
\int_{0}^{T}ds\int_{Y_f}\tilde{\chi_i}|\nabla^2 W(\cdot,s)|^2
+\int_{Y_f}\tilde{\chi_i}|\nabla W(\cdot,t)|^2
\bigg\},
\end{equation*}
which immediately gives the desired estimate $\eqref{pde2.31}$.
The desired estimate is reduced to estimating the first term in the bracket above. We also note that the interior estimate is translation-invariant within $Y_f$, and thus the center position of the estimated region can be disregarded. Therefore, we only need to establish the following estimate:
\begin{equation}\label{pde2.23}
\begin{aligned}
\int_{0}^Tdt\|\nabla^2 W(\cdot,t)\|^2_{L^2(B/2)}




&\lesssim\|\nabla^2\chi\|^2_{L^{\infty}(Y)}
\int_{0}^{T}dt\|\nabla W(\cdot,t)\|^2_{L^2(2B)},
\end{aligned}
\end{equation}
where $B:=B(y,2\rho)$ with $2B\subset \omega$ is arbitrary, and
$\chi\in C^{\infty}_{per}(Y)$ is a cut-off function
satisfying $\chi = 1$ in $B$ and supp$(\chi)\subset 2B$
with $|\nabla\chi|\lesssim \frac{1}{\rho}$. Consequently,
plugging the estimate $\eqref{pde2.23}$ back into $\eqref{pde2.31}$,
we have
\begin{equation*}
\bigg(\int_{Y_f}\chi_i^2|\nabla^2 W(\cdot,t)|^2
\bigg)^{\frac{1}{2}}
\overset{\eqref{pri:3.6}}{\lesssim} \rho^{-3} + \rho^{-1}t^{-\frac{p}{3p-2}}
\lesssim \rho^{-3}t^{-\frac{p}{3p-2}},
\end{equation*}
which is the stated estimate $\eqref{pde2.25}$.

Then, we turn to study the estimate $\eqref{pde2.23}$.
Set $v=\text{curl~}W$ in $\omega\times[0,T]$. By recalling
the equations \eqref{pde2.1}, there holds a new parabolic system:
\begin{equation*}
\left\{
\begin{aligned}
(\partial_t-\Delta)v&=0&\qquad&\text{in}\quad Y_f\times(0,T];\\
v|_{\partial Y_f}&=\text{curl~} W&\qquad&\text{for}\quad  0<t\leq T;\\
v|_{t=0}&=0.&\qquad&
\end{aligned}
\right.
\end{equation*}

For we are interested in the interior estimates, by setting $u=\chi v$,
from the above parabolic system we get
\begin{equation}\label{pde2.20}
\left\{
\begin{aligned}
(\partial_t-\Delta)u&=-\Delta \chi v-2\nabla\chi\cdot\nabla v:=g&\qquad&\text{in}\quad Y_f\times(0,T];\\
u|_{\partial Y_s}&=0,&\qquad&\text{for}\quad 0<t<T;\\
u|_{t=0}&=\chi v|_{t=0}=0.&\qquad&\\
\end{aligned}
\right.
\end{equation}
It is well known from the energy estimate $\eqref{pde2.14}$ that
$v_j\in L^2(0,T;L^2_{per}(Y_f)^d)$,
(where $v_j = \text{curl~}W_j$ represents
the $j^{\text{th}}$ component of $v$.) whereupon we can verify that
each of the components of $g$ belongs to
$L^2(0,T; H^{-1}(Y_{f}))$. Moreover, there holds
\begin{equation*}
\begin{aligned}
\|g(\cdot,t)\|_{H^{-1}(Y_f)}&\lesssim
\|\nabla\chi\cdot\nabla v(\cdot,t)\|_{H^{-1}(\text{supp}(\chi))}
+\|\Delta\chi\|_{L^{\infty}(Y)}
\|v(\cdot,t)\|_{L^2(\text{supp}(\chi))}\\
&\leq\|\nabla^2\chi\|_{L^{\infty}(Y)}
\|v(\cdot,t)\|_{L^2(\text{supp}(\chi))}
\end{aligned}
\end{equation*}
for any $t>0$, and we get
\begin{equation*}
\int_{0}^{T}dt\|g(\cdot,t)\|^2_{H^{-1}
(Y_f)}\lesssim
\|\nabla^2\chi\|^2_{L^{\infty}(Y)}\int_{0}^{T}dt
\int_{2B}|v(\cdot,t)|^2.
\end{equation*}
This together with the energy estimates for \eqref{pde2.20} gives us
\begin{equation}\label{pde2.21}
\|\nabla u\|_{L^2(0,T;L^2(Y_f))}
\lesssim
\|\nabla^2\chi\|_{L^{\infty}(Y)}\bigg(\int_{0}^{T}
\int_{2B}|v|^2\bigg)^{1/2}.
\end{equation}
Recalling the definition of $u$ and $v$, it is not hard to see that
\begin{equation*}
\begin{aligned}
\bigg(\int_{0}^{T}\int_{Y_f}\chi^2|\nabla v|^2\bigg)^{1/2}
&\lesssim
\bigg(
\int_{0}^{T}\int_{Y_f}|\nabla u|^2
\bigg)^{1/2}+
\|\nabla\chi\|_{L^{\infty}(Y)}
\bigg(
\int_{0}^{T}\int_{2B}|v|^2
\bigg)^{1/2}\\
&\overset{\eqref{pde2.21}}{\lesssim}
\|\nabla^2\chi\|_{L^{\infty}(Y)}
\bigg(
\int_{0}^{T}\int_{2B}|v|^2
\bigg)^{1/2},
\end{aligned}
\end{equation*}
and therefore, we have
 \begin{equation}\label{pde2.22}
\bigg(\int_{0}^{T}\int_{B}|\nabla v|^2\bigg)^{1/2}
\lesssim
\|\nabla^2\chi\|_{L^{\infty}(Y)}
\bigg(
\int_{0}^{T}\int_{2B}|v|^2
\bigg)^{1/2}.
\end{equation}

By noting that $v=\text{curl~}W$,
we have $-\Delta W=\text{curl~} v$ in $Y_f\times[0,T]$, where we employ
the vector identity $-\Delta W =\text{curl~}\text{curl~}W-\nabla(\nabla\cdot W)$ (see e.g.  \cite[pp.9]{Tsai18}).
Thus, from the interior $H^2$ estimates for elliptic equation (see e.g. \cite[Chapter 4]{Giaquinta-Martinazzi12}), it follows that
\begin{equation*}
\|\nabla^2 W(\cdot,t)\|_{L^2(B/2)}

\lesssim
\|\nabla \chi\|_{L^{\infty}(Y)}\|\nabla W(\cdot,t)\|_{L^2(B)}+
\|\text{curl~} v(\cdot,t)\|_{L^2(B)}
\end{equation*}
holds for any $t>0$. Hence, integrating both sides above with respect to  $t$ from 0 to $T$, we can derive that
\begin{equation*}
\begin{aligned}
\int_{0}^Tdt\|\nabla^2 W(\cdot,t)\|^2_{L^2(B/2)}
&\lesssim
\|\nabla \chi\|^2_{L^{\infty}(Y)}
\int_{0}^{T}dt\|\nabla W(\cdot,t)\|^2_{L^2(B)}
+\int_{0}^{T}dt\|\nabla v(\cdot,t)\|^2_{L^2(B)}\\
&\overset{\eqref{pde2.22}}{\lesssim}
\|\nabla^2\chi\|^2_{L^{\infty}(Y)}
\bigg\{\int_{0}^{T}dt\|\nabla W(\cdot,t)\|^2_{L^2(B)}
+\int_{0}^{T}dt\|v(\cdot,t)\|^2_{L^2(2B)}\bigg\}\\
&\lesssim\|\nabla^2\chi\|^2_{L^{\infty}(Y)}
\int_{0}^{T}dt\|\nabla W(\cdot,t)\|^2_{L^2(2B)},
\end{aligned}
\end{equation*}
which is the stated estimate $\eqref{pde2.23}$.


\textbf{Step 4.} Show the estimate $\eqref{pde2.26}$.
We start from rewriting the equations $\eqref{pde2.1}$ as follows: for any $t>0$,
\begin{equation*}
\left\{
\begin{aligned}
-\Delta W(\cdot,t)+\nabla \pi(\cdot,t)&=-\partial_t W(\cdot,t) &\quad&\text{in}\quad Y_f;\\
\nabla\cdot W(\cdot,t)&=0&\quad&\text{in}\quad Y_f;\\
W(\cdot,t)|_{\partial Y_s}&=0.&\quad&
\end{aligned}\right.
\end{equation*}

For any $1<p<\infty$, from the $L^p$ theory for
stationary Stokes system (see e.g. \cite[Chapter IV]{Galdi11}), it follows that
\begin{equation}\label{f:3.12}
\|\nabla^2W(\cdot,t)\|_{L^p(Y_f)}
+\|\nabla\pi(\cdot,t)\|_{L^p(Y_f)}
\lesssim
\|\partial_tW(\cdot,t)\|_{L^p(Y_f)},
\end{equation}
where the up to constant depends on $p,d$ and the character of $Y_f$.


Then, for any $p\geq 2$, by using H\"{o}lder's inequality,
the estimate $\eqref{f:3.12}$, and the observation $\partial_t W
=\mathcal{A}W$, as well as,
Stokes semigroup estimates (see e.g. \cite[Chapter 5]{Tsai18}), in the order, we obtain that
\begin{equation*}
\begin{aligned}
\bigg(
\int_{Y_f\setminus(Y_f)_{\rho}}|\Delta W(\cdot,t)|^2
\bigg)^{1/2}
&\lesssim\rho^{\frac{1}{2}-\frac{1}{p}}
\bigg(
\int_{Y_f\setminus(Y_f)_{\rho}}|\nabla^2 W(\cdot,t)|^p
\bigg)^{1/p}\\
&\lesssim
\rho^{\frac{1}{2}-\frac{1}{p}}
\bigg(
\int_{Y_f}|\partial_t W(\cdot,t)|^p
\bigg)^{1/p}
=\rho^{\frac{1}{2}-\frac{1}{p}}
\bigg(
\int_{Y_f}|\mathcal{A} W(\cdot,t)|^p
\bigg)^{1/p}\lesssim \rho^{\frac{1}{2}-\frac{1}{p}}t^{-1},
\end{aligned}
\end{equation*}
which is the desired estimate $\eqref{pde2.26}$.
We have completed the whole proof.

