\label{lemma3.4}
Let $0<T<\infty$, and $2<p<\infty$ with $\vartheta:= \frac{p}{3p-2}$.
Suppose that $(W_j,\pi_j)$ is a weak solution of \eqref{pde2.1}
with $j=1,\cdots,d,$ and the condition $\int_{Y_f}\pi(\cdot,t)=0$ for any $t> 0$.
Then, for any $\alpha>2\vartheta$,
we have a refined weighted estimate
\begin{equation}\label{pri:3.9}
\bigg(\int_{0}^{T}dt\int_{Y_f}|\partial_t W_j(\cdot, t)|^2t^{\alpha}\bigg)^{1/2}
+ \bigg(\int_{0}^{T}dt\int_{Y_f}|\pi_j(\cdot, t)|^2t^{\alpha}\bigg)^{1/2}
\lesssim 1,
\end{equation}
where the up to constant depends on $d$, $\alpha$, $T$, and the character of
$Y_f$.

The advantage of the present proof avoids using advanced analysis results\footnote{The case $\alpha =1$ simply come from a testing function argument, and
we pursue a consistency even in this refined estimate, although there exists
a way to save effort on the pressure term.}.
We firstly establish the weighted estimate for $\partial_t W_j$, and then translate
the same type estimate to the pressure term $\pi_j$. To do so, we take
$\partial_t W_j$ as the test function for the equations $\eqref{pde2.1}$, and for any $t>0$ there holds:
\begin{equation*}
\int_{Y_f}|\partial_t W_j(\cdot,t)|^2
+ \frac{1}{2}\frac{d}{dt}\int_{Y_f}|\nabla W_j(\cdot,t)|^2 = 0.
\end{equation*}
Integrating both sides of the above equation with respect to temporal variable from $\tau$ to $T$,
and then appealing to Lemma $\ref{lemma3.3}$, we obtain that
\begin{equation*}
 \int_{\tau}^{T}\int_{Y_f}|\partial_t W_j|^2
 \leq \frac{1}{2}\int_{Y_f}|\nabla W_j(\cdot,\tau)|^2
 \lesssim \tau^{-2\vartheta}.
\end{equation*}
Multiplying the factor $\tau^{\alpha-1}$ on the both sides above, and then integrating with respect to
$\tau$ from $0$ to $T$, one can further derive that
\begin{equation*}
\int_{0}^{T}d\tau
\bigg(\tau^{\alpha-1}\int_{\tau}^{T}\int_{Y_f}|\partial_t W_j|^2\bigg)
 \lesssim T^{\alpha-2\vartheta}.
\end{equation*}
By using Fubini's theorem in the left-hand side above, i.e.,
\begin{equation*}
\int_{0}^{T}d\tau
\bigg(\tau^{\alpha-1}\int_{\tau}^{T}\int_{Y_f}|\partial_t W_j|^2\bigg)
= \int_{0}^{T}dt\int_{Y_f}|\partial_t W_j(\cdot,t)|^2t^{\alpha},
\end{equation*}
we have established the following estimate
\begin{equation}\label{f:3.13}
 \int_{0}^{T}dt\int_{Y_f}|\partial_t W_j(\cdot,t)|^2t^{\alpha} \lesssim T^{\alpha-2\vartheta}.
\end{equation}

We now continue to study the pressure term, and begin with constructing
an auxiliary function associated with Bogovskii's operator, i.e., for any $t>0$, we have
\begin{equation*}
\left\{
\begin{aligned}
\nabla\cdot v(\cdot,t)&=\pi(\cdot,t),&\quad&\text{in}~Y_f;\\
v(\cdot,t)&=0,&\quad&\text{on}~\partial Y_s,\quad
y\mapsto
v(y,t)~\text{is 1-periodic}
\end{aligned}\right.
\end{equation*}
with the estimate $\|v(\cdot,t)\|_{H^1(Y_f)}
\lesssim\|\pi(\cdot,t)\|_{L^2(Y_f)}$.
By taking $v$ as a test function acting on \eqref{pde2.1}, it is not hard to
get
\begin{equation*}
\int_{Y_f}|\pi_j(\cdot,t)|^2\lesssim\int_{Y_f}|\partial_t W_j(\cdot,t)|^2.
\end{equation*}

Consequently, multiplying $t^\alpha$ on the both sides above and then integrating it
from $0$ to $T$, we obtain
\begin{equation*}
\int_{0}^{T}dt\int_{Y_f}|\pi_j(\cdot,t)|^2t^\alpha
\lesssim \int_{0}^{T}dt\int_{Y_f}|\partial_t W_j(\cdot,t)|^2t^\alpha
\overset{\eqref{f:3.13}}{\lesssim} T^{\alpha-2\vartheta}.
\end{equation*}
This together with $\eqref{f:3.13}$ leads to
the desired estimate $\eqref{pri:3.9}$, and ends the whole proof.

\label{cor:1}
Let $\vartheta$ be given as in Corollary $\ref{lemma3.4}$.
Suppose that $(W_j,\pi_j)$ is a weak solution of \eqref{pde2.1}
with $j=1,\cdots,d$. Then,
for any $1<q<\infty$,
there exists a constant $\lambda\in(0,1]$ as the same as in
Lemma $\ref{lemma2.2}$ such that
a refined decay estimate
\begin{equation}\label{pri:3.10}
\bigg(\int_{Y_f}|\nabla W_j(\cdot, t)|^q\bigg)^{1/q}
\lesssim t^{-\frac{1}{2}+\lambda(\frac{1}{2}-\vartheta)}
\end{equation}
holds for any $t>0$, which further leads to
\begin{equation}\label{pri:3.11}
\|W_j\|_{L^{2}(0,T;W^{1,q}(Y_f))}\lesssim 1,
\end{equation}
where the up to constant depends on $d$, $q$, $\lambda$, $T$, and the character of $Y_f$.

\label{flux}
For any $0<t<T$, let $B(\cdot,t)=\{b_{ij}(\cdot,t)\}_{1\leq i,j\leq d}$
be given as in Propostion $\ref{prop2.1}$. Then there hold
the structure properties:
\begin{equation}\label{eq:3.1}
\emph{(i)}~~\nabla\cdot B(\cdot,t)=0;\qquad\qquad
\emph{(ii)}~~\int_{Y}B(\cdot,t)=0.
\end{equation}
Moreover, there exists $\Phi(\cdot,t)=\{\Phi_{ki,j}(\cdot,t)\}_{1\leq i,j,k\leq d}$
with $\Phi_{ki,j}(\cdot,t)\in H^{1}_{\emph{loc}}(\mathbb{R}^d)$
being 1-periodic, and satisfying
\begin{equation}\label{pde:3.5}
 \nabla \cdot \Phi(\cdot, t) =
 B(\cdot,t)\quad \text{in}\quad Y
\end{equation}
under the antisymmetry condition (i.e., $\Phi_{ki,j}=-\Phi_{ik,j}$).
Also, for any $1<q<\infty$, we have the regularity estimate
\begin{equation}\label{pri:3.8}
\|\Phi(\cdot,t)\|_{W^{1,q}(Y)}\lesssim \|B(\cdot,t)\|_{L^q(Y)},
\end{equation}
where the up to constant is independent of $t$.

\label{lemma3.6-1}
Let $0<T<\infty$. Given $f\in L^2(0,T;C^{1,\frac{1}{2}}(\bar\Omega)^d)$, assume
the same geometry assumptions on perforated domains as in Theorem
$\ref{thm1}$.
Let $J_1$ and $J_2$ be given as in $\eqref{pde3.8}$. Then, for a.e. $t\geq 0$,
there exists at least
one weak solution to
\begin{equation}\label{divc2}
\left\{
\begin{aligned}
\nabla\cdot\xi_{\varepsilon}(\cdot,t)&=\frac{\partial J_2}{\partial t} +\sum_{i} (\Xint-_{O_{\varepsilon}^i}\frac{\partial J_1}{\partial t})1_{O_{\varepsilon}^i},&
\text{in}&\quad \Omega_{\varepsilon};\\
\xi_{\varepsilon}(\cdot,t)&=0,&\text{on}&\quad \partial \Omega_{\varepsilon},
\end{aligned}\right.
\end{equation}
where we recall that $1_{O_{\varepsilon}^i}$ is the indicator function of $O_{\varepsilon}^i$, and $\{O_{\varepsilon}^i\}$ is a family of the non-overlap subsets of $O_\varepsilon$, satisfying $\eqref{k-5}$. Also,
the solution satisfies the following estimate
\begin{equation}\label{pri:4.1}
 \|\xi_{\varepsilon}\|_{L^2(0,T;L^2(\Omega_\varepsilon))}
 + \varepsilon\|\nabla\xi_{\varepsilon}\|_{L^2(0,T;L^2(\Omega_\varepsilon))}
 \lesssim \varepsilon^{1/2}\|f\|_{L^2(0,T;C^{1,1/2}(\bar{\Omega}))},
\end{equation}
in which the up to constant depends on $d$, $|Y_f|$, $T$, and the characters of $Y_f$ and $\Omega$.

\label{lemma3.6-2}
Assume the same conditions as in Theorem $\ref{thm1}$.
Let $J_1$ be given as in $\eqref{pde3.8}$. Then,
for a.e. $t\geq 0$,  there exists at least
one weak solution to
\begin{equation}\label{divc3}
\left\{
\begin{aligned}
\nabla\cdot\eta_{\varepsilon}(\cdot,t)&=\frac{\partial J_1}{\partial t} -\sum_{i} (\Xint-_{O_{\varepsilon}^i}\frac{\partial J_1}{\partial t})1_{O_{\varepsilon}^i},&
\text{in}&\quad O_{\varepsilon};\\
\eta_{\varepsilon}(\cdot,t)&=0,&\text{on}&\quad \partial O_{\varepsilon},
\end{aligned}\right.
\end{equation}
satisfying the following estimate
\begin{equation}\label{pri:5.2}
 \|\eta_{\varepsilon}\|_{L^2(0,T;L^2(\Omega_\varepsilon))}
 + \varepsilon\|\nabla\eta_{\varepsilon}\|_{L^2(0,T;L^2(\Omega_\varepsilon))}
 \lesssim \varepsilon^{1/2}\|f\|_{L^2(0,T;C^{1,1/2}(\bar{\Omega}))},
\end{equation}
where the up to constant depends on $d$, $|Y_f|$, $T$, and the characters of $Y_f$ and $\Omega$.

\begin{equation}\label{divc3}
\left\{
\begin{aligned}
\nabla\cdot\eta_{\varepsilon}(\cdot,t)&=\frac{\partial J_1}{\partial t} -\sum_{i} (\Xint-_{O_{\varepsilon}^i}\frac{\partial J_1}{\partial t})1_{O_{\varepsilon}^i},&
\text{in}&\quad O_{\varepsilon};\\
\eta_{\varepsilon}(\cdot,t)&=0,&\text{on}&\quad \partial O_{\varepsilon},
\end{aligned}\right.
\end{equation}

\label{lemma3.6-3}
Suppose $\xi_{\varepsilon}$ and $\eta_{\varepsilon}$ are the two solutions of $\eqref{divc2}$ and $\eqref{divc3}$ given in Propositions $\ref{lemma3.6-1}$ and $\ref{lemma3.6-2}$, respectively.
Let $\hat{\xi_{\varepsilon}}$ and $\hat{\eta_{\varepsilon}}$ be defined as in $\eqref{pde3.11}$\footnote{Note that
$\eta_{\varepsilon}$ can be trivially zero-extended to the whole region $\Omega$.}:
Moreover, there also hold the regularity estimates:
\begin{subequations}
\begin{align}
\|\hat\xi_{\varepsilon}\|_{L^2(0,T;L^2(\Omega_\varepsilon))}
+ \varepsilon\|\nabla\hat\xi_{\varepsilon}\|_{L^2(0,T;L^2(\Omega_\varepsilon))}
&\lesssim \varepsilon^{1/2}\|f\|_{L^2(0,T;C^{1,1/2}(\bar\Omega))}; \label{pri:5.3a} \\
\|\hat\eta_{\varepsilon}\|_{L^2(0,T;L^2(\Omega_\varepsilon))}
+ \varepsilon\|\nabla\hat\eta_{\varepsilon}\|_{L^2(0,T;L^2(\Omega_\varepsilon))}
&\lesssim \varepsilon^{1/2}\|f\|_{L^2(0,T;C^{1,1/2}(\bar\Omega))}, \label{pri:5.3b}
\end{align}
\end{subequations}
where the multiplicative constant depends on $d$, $|Y_f|$, $T$, and the characters of
$Y_f$ and $\Omega$.

\label{thm4}
Assume the same geometry assumptions on the perforated domain
as in Theorem $\ref{thm1}$. Then, for any $g\in L^2(\Omega_{\varepsilon})$ with
$\int_{\Omega_{\varepsilon}}g =0$,
there exists a vector-valued function
$v_{\varepsilon}\in H^{1}_0(\Omega_{\varepsilon})^d$
such that $\nabla\cdot v_{\varepsilon} =g$ in $\Omega_\varepsilon$, satisfying
\begin{equation}\label{pde3.21}
\| v_{\varepsilon}
\|_{L^2(\Omega_{\varepsilon})}
\leq C\varepsilon\|\nabla v_{\varepsilon}
\|_{L^2(\Omega_{\varepsilon})}
\leq C
\|g\|_{L^2(\Omega_{\varepsilon})},
\end{equation}
where the constant $C$ is independent of $\varepsilon$ and $g$.

\label{lemma:cut-off}
Let $\Omega\subset\mathbb{R}^d$ be a bounded $C^2$ domain. Then, for any $0<\varepsilon\ll 1$,
there exists a cut-off function $\psi_{\varepsilon}$ satisfying
the following properties:
\emph{\begin{itemize}
\item[\text{(a).}] $\psi_{\varepsilon}\in C^\infty_0(\Omega)$
with supp$(\psi_{\varepsilon})=\Sigma_{\varepsilon}$,
$\psi_{\varepsilon}=1$ on $\Sigma_{2\varepsilon}$ and
$0\leq \psi_{\varepsilon}\leq 1$ (where $\Sigma_\varepsilon$ is defined in Subsection $\ref{notation}$);
\item[\text{(b).}] For any $x$ with $\text{dist}(x,\partial\Omega)<10\varepsilon$, there exists
a unique element $\tilde{x}\in\partial\Omega$ such that dist$(x,\partial\Omega)=|x-\tilde{x}|$ and $\tilde{x}\in \partial\Omega$, and there also holds
\begin{equation}\label{eq:5.1}
\nabla \psi_{\varepsilon}(x)=-|\nabla \psi_{\varepsilon}(x)|\vec{n}(\tilde{x})
\quad \text{on}~O_\varepsilon,
\end{equation}
where $O_{\varepsilon}:=$supp$(\nabla\psi_{\varepsilon})\subset \Omega\setminus\Sigma_{2\varepsilon}$; Also, we have
$|\nabla\psi_{\varepsilon}(x)|=|\nabla\psi_{\varepsilon}(y)|$, provided
dist$(x,\partial\Omega)=$dist$(y,\partial\Omega)$ for $x,y\in O_{\varepsilon}$;
\item[\text{(c).}] $|\nabla\psi_{\varepsilon}|
    \lesssim\frac{1}{\varepsilon}$ and $|\nabla^2\psi_{\varepsilon}|\lesssim
    \frac{1}{\varepsilon^2}$.
\end{itemize}}

\label{remark:4.1}
\emph{As mentioned in Proposition $\ref{subsec:1.2}$,
$\{O_{\varepsilon}^i\}$ is a family of the non-overlap subsets of $O_\varepsilon$, such that
\begin{equation*}
\begin{aligned}
&O_\varepsilon = \bigcup_{i}O_\varepsilon^{i}
\quad\text{and}\quad
|O_\varepsilon^i| \sim \varepsilon^d,
\end{aligned}
\end{equation*}
in which $O_\varepsilon^{i}$ is an approximately $d$-dimensional cube obtained by cutting $O_\varepsilon$ in the normal direction $\vec{n}$ associated with $\partial\Omega$ (see Figure $\ref{subfig_1}$ for an example). The boundary of $O_\varepsilon^i$ consists of two parts:
\begin{itemize}
  \item[(a).] $\{R_j^i\}:= \partial O_\varepsilon^i\cap \partial O_\varepsilon$. Let $\vec{n}_R$ be the unit normal vector of $R_j^i$, satisfying $\vec{n}_R \perp R_j^i$. Then, there holds
      \begin{equation*}
         \vec{n}_R \kern 0.56em/\kern -0.8em /\kern 0.56em \vec{n} \quad\text{on}\quad R_j^i.
      \end{equation*}
  \item[(b).]
$\{S_j^i\}:= \partial O_\varepsilon^i\cap O_\varepsilon$. Let $\vec{n}_S$ be the unit normal vector of $S_j^i$,
satisfying $\vec{n}_S \perp S_j^i$. Due to $S_j^i$ obtained by the cutting in the normal direction $\vec{n}$, we have the following relationship:
\begin{equation}\label{k-6}
 \vec{n}_S \perp \vec{n} \quad\text{on}\quad S_j^i.
\end{equation}
\end{itemize}}

\label{lemma:5.1}
Let $\psi_\varepsilon$ be the radial cut-off function defined in
Lemma $\ref{lemma:cut-off}$, and $J_2$ be given
as in $\eqref{pde3.8}$. Assume the same conditions as in
Proposition $\ref{lemma3.6-1}$. Then,
the first term in the right-hand side of $\eqref{divc2}$ satisfies the following estimate
\begin{equation}\label{pri:5.1}
\begin{aligned}
\bigg(
\int_{0}^{T}dt\int_{\Omega_{\varepsilon}}
&\big|\frac{\partial J_2}{\partial t}\big|^2
\bigg)^{1/2}
\lesssim
\varepsilon^{\frac{1}{2}}
\Big(\|\partial_t \phi\|_{L^1(0,T;L^2(Y))}
+\|\phi(\cdot,0)\|_{L^2(Y_f)}
\Big)
\|(\nabla G,\varepsilon^{\frac{1}{2}}\nabla^2G)\|_{L^2(0,T;
L^{\infty}(\text{supp}(\psi_{\varepsilon})))}\\
&+
\Big(\|\partial_tA\|_{L^1(0,T)}+|A(0)|\Big)
\bigg\{\varepsilon^{\frac{1}{2}}\|\nabla F\|_{L^2(0,T;C(\bar{\Omega}))}
+\|\nabla(G-F)\|_{
L^2(0,T;L^2{(\text{supp}(\psi_{\varepsilon}))})}\bigg\},\\
\end{aligned}
\end{equation}
where the multiplicative constant depends on
$d$, $|Y_f|$, and the character of $\Omega$,
but independent of $\varepsilon$.

By virtue of the equality $\eqref{eq:5.1}$, together with
the structure of the effective solution, we can find a cancellation near the boundary with respect to
outward normal direction, which further provides us with the desired smallness.
For the sake of the convenience, we recall the expression of $J_2$, as well as, the convention in $\eqref{notation:4.2}$,
and denote it by
\begin{equation}\label{f:5.11}
\begin{aligned}
  J_2&=\nabla \psi_{\varepsilon}
  \cdot (A\ast G)
  +\varepsilon\nabla \psi_{\varepsilon}\cdot
  \big(\phi_{\varepsilon}\ast_2 \partial G\big)
  +\psi_{\varepsilon}\frac{A}{|Y_f|}\ast_2 \partial G
  +\varepsilon\psi_{\varepsilon}\phi_{\varepsilon}
  \ast_3\partial^2G\\
  &:=J_{21}+J_{22}+J_{23}+J_{24}.
  \end{aligned}
\end{equation}
We complete the whole arguments by three steps, according to the similarity of the computations.


\textbf{Step 1}. We start from the term $\frac{\partial J_{21}}{\partial t}$,
and it follows from the equality $\eqref{eq:5.1}$ that
\begin{equation}\label{f:5.9}
\begin{aligned}
\frac{\partial J_{21}}{\partial t}
= \nabla \psi_{\varepsilon}\cdot \frac{\partial }{\partial t}( A\ast G)
&= -|\nabla\psi_\varepsilon|\vec{n}\cdot \frac{\partial }{\partial t}( A\ast G)\\
&=-|\nabla\psi_\varepsilon|\vec{n}\cdot \frac{\partial }{\partial t}\big[A\ast (G-F)\big] -|\nabla\psi_\varepsilon|\vec{n}\cdot \frac{\partial }{\partial t}( A\ast F).
\end{aligned}
\end{equation}
By noting the fact that $|\nabla\psi_{\varepsilon}|\lesssim
\varepsilon^{-1}$ (see Lemma $\ref{lemma:cut-off}$), there holds
\begin{equation}\label{f:5.10}
\begin{aligned}
\int_{0}^{T}dt\int_{\Omega_{\varepsilon}}\Big|\frac{\partial J_{21}}{\partial t}\Big|^2
&\overset{\eqref{f:5.9}}{\lesssim} \varepsilon^{-2}
\int_{0}^{T}dt\int_{O_{\varepsilon}}
|\vec{n}\cdot\frac{\partial }{\partial t}( A\ast F)|^2
+\varepsilon^{-2}
\int_{0}^{T}dt\int_{O_{\varepsilon}}
|\vec{n}\cdot\frac{\partial }{\partial t}[ A\ast (G-F)]|^2.
\end{aligned}
\end{equation}
To handle the first term in the right-hand side above,
recalling the effective equations $\eqref{pde1.2}$, we have
$u_0=A\ast F$ with $\vec{n}\cdot u_0=0$ on the boundary $\partial\Omega\times(0,T)$,
whereupon for any $x\in O_\varepsilon$ and $t\geq 0$ there holds
\begin{equation*}
\vec{n}\cdot
\frac{\partial}{\partial t}\big(A\ast F\big)(x,t)
=\vec{n}\cdot \int_{0}^{1}ds\nabla
\frac{\partial}{\partial t}\big(A\ast F\big)(\tilde{x}+s(x-\tilde{x}),t)
\cdot(x-\tilde{x}),
\end{equation*}
where $\tilde{x}\in\partial\Omega$ is such that $\text{dist}(x,\partial\Omega)
=|x-\tilde{x}|$,
which further implies
\begin{equation*}
\int_{O_\varepsilon}\Big|\vec{n}\cdot \frac{\partial}{\partial t}
\big(A\ast F\big)(\cdot,t)\Big|^2
\lesssim \varepsilon^2
\int_{O_\varepsilon}\int_{0}^{1}ds
\big|\nabla \frac{\partial}{\partial t}\big(A\ast F\big)
(\tilde{x}+s(\cdot
-\tilde{x}),t)\big|^2
\leq \varepsilon^2\int_{\Omega\setminus \Sigma_{2\varepsilon}}
|\nabla \frac{\partial}{\partial t}\big(A\ast F\big)(\cdot,t)|^2.
\end{equation*}
Plugging this back into $\eqref{f:5.10}$, and using
Young's inequality,  we obtain that
\begin{equation*}
\begin{aligned}
&\quad\int_{0}^{T}dt\int_{\Omega_{\varepsilon}}\Big|\frac{\partial J_{21}}{\partial t}\Big|^2
\lesssim
\int_{0}^{T}dt
\int_{\Omega}
|\nabla\frac{\partial }{\partial t}( A\ast F)|^2
+\varepsilon^{-2}
\int_{0}^{T}dt
\int_{O_{\varepsilon}}
\big(|(\partial_tA)\ast (G-F)|^2+|A(0)(G-F)|^2\big)\\
&\lesssim
\int_{0}^{T}dt\int_{\Omega\setminus\Sigma_{2\varepsilon}}
\big(|(\partial_tA)\ast \nabla F|^2+|A(0)\nabla F|^2\big)+\varepsilon^{-2}
\int_{0}^{T}dt\int_{O_{\varepsilon}}
\big(|(\partial_tA)\ast (G-F)|^2+|A(0)(G-F)|^2\big)\\
&\lesssim
\big(\|\partial_tA\|_{L^1(0,T)}^2+|A(0)|^2\big)
\Big\{\varepsilon\|\nabla F\|_{L^2(0,T;C(\bar{\Omega}))}^2
+ \varepsilon^{-1}\|G-F\|_{L^2(0,T;L^\infty(\text{supp}
(\psi_{\varepsilon})))}^2 \Big\}.
\end{aligned}
\end{equation*}
This, together with the estimate (Recall the notations $G,F$ in Subsection $\ref{notation}$.)
\begin{equation*}
\|G(\cdot,t)
-F(\cdot,t)\|_{L^\infty(\text{supp}
(\psi_{\varepsilon}))}\lesssim\varepsilon
\|\nabla F(\cdot,t)\|_{C(\bar\Omega)},
\end{equation*}
immediately yields
\begin{equation}\label{*xi2}
\int_{0}^{T}dt\int_{\Omega_{\varepsilon}}\Big|\frac{\partial J_{21}}{\partial t}\Big|^2
\lesssim \varepsilon
\big(\|\partial_tA\|_{L^1(0,T)}^2+|A(0)|^2\big)
\|\nabla F\|_{L^2(0,T;C(\bar{\Omega}))}^2.
\end{equation}


\textbf{Step 2}. We turn to study the term $J_{23}$.
Appealing to
the fact that $\nabla\cdot u_0=A\ast_2\partial F=0$ in $\Omega\times(0,T)$,
there holds
\begin{equation*}
\begin{aligned}
  \int_{0}^{T}dt\int_{\Omega_{\varepsilon}}\Big|
  \frac{\partial J_{23}}{\partial t}
  \Big|^2
  &=
  \int_{0}^{T}dt\int_{\Omega_{\varepsilon}}\Big|
  \frac{\psi_{\varepsilon}}{|Y_f|}
  \frac{\partial}{\partial t}(A\ast_2\partial G)
  \Big|^2
  =\int_{0}^{T}dt\int_{\Omega_{\varepsilon}}\Big|
  \frac{\psi_{\varepsilon}}{|Y_f|}
  \frac{\partial}{\partial t}[A\ast_2\partial (G-F)]\Big|^2\\
  &=\int_{0}^{T}dt\int_{\Omega_{\varepsilon}}\Big|
  \frac{\psi_{\varepsilon}}{|Y_f|}
  \Big(\big[(\partial_tA)\ast_2\partial (G-F)\big]
  +A(0):\partial (G-F)\Big)\Big|^2.
\end{aligned}
\end{equation*}
By using Minkowski's inequality and Young's inequality, the above equality
gives us
\begin{equation}\label{*xi3}
\int_{0}^{T}dt\int_{\Omega_{\varepsilon}}\Big|
\frac{\partial J_{23}}{\partial t}
\Big|^2\lesssim
\big(\|\partial_tA\|^2_{L^1(0,T)}+|A(0)|^2\big)
\|\nabla(G-F)\|^2_{
L^2(0,T;L^2{(\text{supp}(\psi_{\varepsilon}))})}.
\end{equation}


\textbf{Step 3}.
Due to the analogous computations, we consider the terms $J_{22}$ and $J_{24}$ together, and start from
the following estimate:
\begin{equation*}
  \begin{aligned}
  \int_{0}^{T}dt\int_{\Omega_{\varepsilon}}
  \bigg|\frac{\partial J_{22}}{\partial t}+\frac{\partial J_{24}}{\partial t}\bigg|^2
  &\lesssim
  \int_{0}^{T}\int_{\Omega_{\varepsilon}}
  \bigg|\varepsilon\nabla\psi_{\varepsilon}(x)\cdot
  \frac{\partial}{\partial t}(\phi_{\varepsilon}\ast_2\partial G)\bigg|^2 +
  \int_{0}^{T}\int_{\Omega_{\varepsilon}}
 \bigg|\varepsilon\psi_{\varepsilon}\frac{\partial}
  {\partial t}(\phi_{\varepsilon}\ast_3\partial^2 G)\bigg|^2 \\
  &\lesssim
  \int_{0}^{T}\int_{O_{\varepsilon}}
  \big(|(\partial_t\phi_{\varepsilon})\ast_2\partial G|^2
  +|\phi_{\varepsilon}(\cdot,0):\partial G|^2\big) \\
  &\qquad+\varepsilon^2
  \int_{0}^{T}\int_{\text{supp}(\psi_{\varepsilon})}
  \Big(|(\partial_t\phi_{\varepsilon})\ast_3\partial^2G|^2
  +|\phi_{\varepsilon}(\cdot,0)|^2|\nabla^2G|^2\Big).
  \end{aligned}
\end{equation*}
Using Minkowski's inequality and Young's inequality, we have
\begin{equation*}
\begin{aligned}
\int_{0}^{T}dt\int_{O_{\varepsilon}}
  \Big(|(\partial_t\phi_{\varepsilon})\ast_2\partial G(\cdot,t)|^2
&  +|\phi_{\varepsilon}(\cdot,0):\partial G(\cdot,t)|^2\Big)\\
&\lesssim
\varepsilon\Big\{\|\partial_t\phi\|^2_{
L^1(0,T;L^2(Y_f))}
+\|\phi(\cdot,0)\|^2_{L^2(Y_f)}\Big\}
\|\nabla G\|^2_{L^2(0,T;L^{\infty}
(\text{supp}(\psi_{\varepsilon})))},
\end{aligned}
\end{equation*}
and it similarly follows that
\begin{equation*}
\begin{aligned}
\int_{0}^{T}dt\int_{\text{supp}(\psi_{\varepsilon})}
  \Big(|(\partial_t\phi_{\varepsilon})\ast_3\partial^2
  &G(\cdot,t)|^2
  +|\phi_{\varepsilon}(\cdot,0)|^2|\nabla^2G(\cdot,t)|^2\Big)\\
&\lesssim
\varepsilon^2
\Big\{\|\partial_t\phi\|^2_{L^1(0,T;L^2(Y_f))}
+\|\phi(\cdot,0)
\|^2_{L^2(Y_f)}\Big\}
\|\nabla^2G\|^2_{L^2(0,T;L^{\infty}
(\text{supp}(\psi_{\varepsilon})))}.
\end{aligned}
\end{equation*}
Thus, combining the three estimates above, we derive that
\begin{equation}\label{*xi1}
\begin{aligned}
&\quad\int_{0}^{T}dt\int_{\Omega_{\varepsilon}}\Big|\frac{\partial J_{22}}{\partial t}
+\frac{\partial J_{24}}{\partial t}\Big|^2 \\
&\lesssim
\varepsilon\Big(\|\partial_t\phi\|^2_{L^1(0,T;L^2(Y_f))}
+\|\phi(\cdot,0)\|^2_{L^2(Y_f)}\Big)
\|(\nabla G,\varepsilon^{\frac{1}{2}}\nabla^2G)\|^2_{L^2(0,T;L^{\infty}
(\text{supp}(\psi_{\varepsilon})))}.
  \end{aligned}
\end{equation}


Consequently, the desired estimate $\eqref{pri:5.1}$
follows from the estimates $\eqref{f:5.11}$, $\eqref{*xi2}$, $\eqref{*xi3}$,
