\textbf{Step 4.} Arguments for $E_2^i(t)$ in $\eqref{pri:4.4}$.
According to Remark $\ref{remark:4.1}$,
we rewrite $E_{2}^i(t)$ as follows:
\begin{equation}\label{}
\begin{aligned}
E_{2}^i(t)
  =\frac{\partial}{\partial t}
  \int_{\partial O_{\varepsilon}^i\cap \partial O_\varepsilon}dS
  &\big[\Phi^\varepsilon\ast_3 \big(G
  \otimes(\varepsilon\nabla\psi_{\varepsilon})\otimes
  \vec{n}_R\big)\big](\cdot,t) \\
&+ \frac{\partial}{\partial t}
  \int_{\partial O_{\varepsilon}^i\cap O_\varepsilon}dS
  \big[\Phi^\varepsilon\ast_3
  \big(G\otimes(\varepsilon\nabla\psi_{\varepsilon})\otimes
  \vec{n}_S\big)\big](\cdot,t).
\end{aligned}
\end{equation}

On the one hand, it follows from
the property (a) presented in Remark $\ref{remark:4.1}$ that
\begin{equation*}
(\varepsilon\nabla\psi_\varepsilon)\otimes \vec{n}_R =
\vec{n}_R\otimes(\varepsilon\nabla\psi_\varepsilon)
  \qquad \text{on}\quad \partial O_\varepsilon^i\cap \partial O_\varepsilon,
\end{equation*}
and this together with the antisymmetric property of $\Phi$ leads to
\begin{equation}\label{k-9}
\frac{\partial}{\partial t}
  \int_{\partial O_{\varepsilon}^i\cap \partial O_\varepsilon}dS
  \big[\Phi^\varepsilon\ast_3 \big(G
  \otimes(\varepsilon\nabla\psi_{\varepsilon})\otimes
  \vec{n}_R\big)\big](\cdot,t) = 0.
\end{equation}


On the other hand, using the antisymmetric property again,
we first notice that
\begin{equation*}
\big[\Phi^\varepsilon\ast_3 (G\otimes
  \vec{n}_S\otimes
  \vec{n}_S)\big](\cdot,t)
  =\int_{0}^{t}ds\Phi_{ij,k}(\cdot/\varepsilon,t-s)\big(G_k
  \vec{n}_S^i\vec{n}_S^j\big)(\cdot,s)=0
  \qquad\text{on}\quad \partial O_\varepsilon^i\cap O_\varepsilon,
\end{equation*}
where we employ the fact that $\vec{n}_S\otimes
  \vec{n}_S$ is a symmetric matrix.
Therefore, for any $N>0$, it follows that
\begin{equation*}
\begin{aligned}
&E_{2}^i(t)
  \overset{\eqref{k-9}}{=} \frac{\partial}{\partial t}
  \int_{\partial O_{\varepsilon}^i\cap O_\varepsilon}dS
  \big[\Phi^\varepsilon\ast_3
  \big(G\otimes(\varepsilon\nabla\psi_{\varepsilon})\otimes
  \vec{n}_S\big)\big](\cdot,t) \\
  &= \frac{\partial}{\partial t}
  \int_{\partial O_{\varepsilon}^i\cap O_\varepsilon}dS
  \big[\Phi^\varepsilon\ast_3 (G\otimes
  \big(\varepsilon\nabla\psi_{\varepsilon}+N\vec{n}_S\big)\otimes
  \vec{n}_S)\big](\cdot,t)
  -N\varepsilon \frac{\partial}{\partial t}
  \int_{\partial O_{\varepsilon}^i\cap O_\varepsilon}dS
  \big[\Phi^\varepsilon\ast_3 (G\otimes
  \vec{n}_S\otimes
  \vec{n}_S)\big](\cdot,t) \\
  &= \frac{\partial}{\partial t}\int_{\partial O_{\varepsilon}^i
  \cap O_\varepsilon}dS
  \big[\Phi^\varepsilon\ast_3 (G\otimes
  \big(\varepsilon\nabla\psi_{\varepsilon}+N\vec{n}_S\big)\otimes
  \vec{n}_S)\big](\cdot,t).
\end{aligned}
\end{equation*}

Then, taking $N\to\infty$,
if the right-hand side above vanishes, one can obtain
the desired equality $\eqref{pri:4.4}$. This is true
and we show it in the following.



On the one hand, we can start from the following observation
\begin{equation}\label{pri:4.3}
\lim_{N\to\infty}
  \big[\Phi^\varepsilon\ast_3 (G\otimes
  \big(\varepsilon\nabla\psi_{\varepsilon}+N\vec{n}_S\big)\otimes
  \vec{n}_S)\big](\cdot,t) = 0
  \qquad\text{on}~~\partial O_\varepsilon^i\cap O_\varepsilon,
\end{equation}
which comes from the fact that $\varepsilon\nabla\psi_{\varepsilon}+N\vec{n}_S$  becomes linearly dependent on $\vec{n}_S$, i.e.,
\begin{equation*}
  \cos\theta = \frac{\big(\varepsilon\nabla\psi_\varepsilon+N\vec{n}_S\big)\cdot
  \vec{n}_S}{\sqrt{N^2+c}} = \frac{N}{\sqrt{N^2+c}} \to 1
\qquad\text{as}
\qquad N\to\infty,
\end{equation*}
where we employ the geometry fact $\eqref{k-6}$ by noting that
$\varepsilon\nabla\psi_\varepsilon\sim \vec{n}$.
In other words, we have
\begin{equation*}
\big(\varepsilon\nabla\psi_{\varepsilon}+N\vec{n}_S\big)\otimes
  \vec{n}_S -
  \vec{n}_S\otimes
  \big(\varepsilon\nabla\psi_{\varepsilon}+N\vec{n}_S\big)\to 0,
\qquad\text{as}\qquad N\to\infty.
\end{equation*}
and this together with the antisymmetric property of $\Phi$ gives
$\eqref{pri:4.3}$.

One the other hand, for any fixed $i$ and $\varepsilon$, $E_{2}^i(t)$ is unform bounded with
respect to any $t\in[0,T]$ and $N>0$. Therefore, we have
\begin{equation*}
\begin{aligned}
\lim_{N\to\infty}\frac{\partial}{\partial t}\int_{\partial O_{\varepsilon}^i\cap O_\varepsilon}
&dS
  \big[\Phi^\varepsilon
\ast_3 (G
\otimes
  \big(\varepsilon\nabla\psi_{\varepsilon}
+N\vec{n}_S\big)\otimes
  \vec{n}_S)\big](\cdot,t)\\
&=
\frac{\partial}{\partial t}\Big(
\lim_{N\to\infty}
\int_{\partial O_{\varepsilon}^i\cap O_\varepsilon}dS
  \big[\Phi^\varepsilon\ast_3 (G\otimes
  \big(\varepsilon\nabla\psi_{\varepsilon}+N\vec{n}_S\big)\otimes
  \vec{n}_S)\big](\cdot,t)\Big)\\
&\qquad\qquad\quad=\frac{\partial}{\partial t}
\int_{\partial O_{\varepsilon}^i\cap O_\varepsilon}dS\Big(
\lim_{N\to\infty}
  \big[\Phi^\varepsilon\ast_3 (G\otimes
  \big(\varepsilon\nabla\psi_{\varepsilon}+N\vec{n}_S\big)\otimes
  \vec{n}_S)\big](\cdot,t)\Big) \overset{\eqref{pri:4.3}}{=}0,
\end{aligned}
\end{equation*}
where we employed Lebesgue's dominated convergence theorem
for the second equality. This gives $\eqref{pri:4.4}$.

Finally, we note that the fact that $\eqref{pri:4.4}$ holds uniformly with respect to $i$ and $t\in(0,T]$ is based on consistent geometric features
(i.e., $\nabla\psi_\varepsilon\cdot n_S =0$ on $\partial O_\varepsilon^i
\cap O_\varepsilon$ for each $i$ due to $\eqref{k-6}$) and the same algebraic principles
(i.e., ``the second-order inner product of an antisymmetric matrix and a symmetric matrix is equal to zero.''). This completes all the proofs.

