\medskip

\textbf{Part 2.} We now check the divergence-free condition of $w_{\varepsilon}$.
It follows that
\begin{equation*}
\nabla\cdot w_{\varepsilon}=\nabla\cdot u_{\varepsilon}-\nabla\cdot
\bigg\{
\psi_{\varepsilon}\big[W^{\varepsilon}\ast G+\varepsilon\phi^{\varepsilon}
\ast_2 \partial G\big]
\bigg\}
+\nabla\cdot\hat{\xi_{\varepsilon}}+\nabla\cdot\hat{\eta_{\varepsilon}},
\end{equation*}
and it suffices to show
\begin{equation}\label{f:4.6}
\nabla\cdot \bigg\{
\psi_{\varepsilon}[W^{\varepsilon}\ast G+\varepsilon\phi^{\varepsilon}\ast_2 \partial G]
\bigg\} = \nabla\cdot\hat{\xi_{\varepsilon}} + \nabla\cdot\hat{\eta_{\varepsilon}}.
\end{equation}

\medskip

By divergence-free condition of $\eqref{pde2.1}$ and the equations $\eqref{divc1*}$
that $\phi$ satisfies, we obtain that
\begin{equation*}
\begin{aligned}
&\quad\nabla\cdot
\bigg\{
\psi_{\varepsilon}[W^{\varepsilon}\ast G+\varepsilon\phi^{\varepsilon}\ast_2 \partial G]
\bigg\}\\
&=\nabla\psi_{\varepsilon}\cdot[W^{\varepsilon}\ast G+\varepsilon\phi^{\varepsilon}\ast_2\partial G]
+\psi_{\varepsilon}\nabla\cdot[W^{\varepsilon}\ast G+\varepsilon\phi^{\varepsilon}\ast_2\partial G]\\
&=\nabla\psi_{\varepsilon}\cdot[W^{\varepsilon}\ast G+\varepsilon\phi^{\varepsilon}\ast_2\partial G]
+\psi_{\varepsilon}\bigg[
\varepsilon^{-1}(\nabla\cdot W)^{\varepsilon}\ast_1 G+W^{\varepsilon}\ast_2\partial G
+(\nabla\cdot\phi)^{\varepsilon}\ast_2\partial G
+\varepsilon\phi^{\varepsilon}\ast_{3}\partial^2 G
\bigg]\\
&\overset{\eqref{divc1*}}{=}\nabla\psi_{\varepsilon}\cdot[W^{\varepsilon}\ast G+\varepsilon\phi^{\varepsilon}\ast_2\partial G]
+\psi_{\varepsilon}W^{\varepsilon}\ast_2\partial G
+\psi_{\varepsilon}
(\frac{A}{|Y_f|}-W^{\varepsilon}
)\ast_2\partial G
+\varepsilon\psi_{\varepsilon}
\phi^{\varepsilon}\ast_3\partial^2 G\\
&=
\nabla\psi_{\varepsilon}\cdot[W^{\varepsilon}\ast G+\varepsilon\phi^{\varepsilon}\ast_2\partial G]
+\psi_{\varepsilon}
\frac{A}{|Y_f|}\ast_2\partial G
+\varepsilon\psi_{\varepsilon}
\phi^{\varepsilon}\ast_3\partial^2G,
\end{aligned}
\end{equation*}
and this further implies
\begin{equation}\label{f:4.5}
\begin{aligned}
&\quad\nabla\cdot
\bigg\{
\psi_{\varepsilon}[W^{\varepsilon}\ast G+\varepsilon\phi^{\varepsilon}\ast_2 \partial G]
\bigg\}\\
&=\nabla\psi_{\varepsilon}\cdot\big[(W^{\varepsilon}
-A)\ast G\big]
+\nabla\psi_{\varepsilon}\cdot(A\ast G)
+\psi_{\varepsilon}
\frac{A}{|Y_f|}\ast_2\partial G
+\varepsilon\nabla\psi_{\varepsilon}
\cdot\big(\phi^{\varepsilon}\ast_2\partial G\big)
+\varepsilon\psi_{\varepsilon}
\phi^{\varepsilon}\ast_3\partial^2G.
\end{aligned}
\end{equation}

