\begin{equation}\label{f:6.4}
\begin{aligned}
 \int_{\Omega_{\varepsilon,T}}
 |\partial_t w_\varepsilon|^2
 + \varepsilon^2\int_{\Omega_\varepsilon}|\nabla w_\varepsilon(\cdot,T)|^2
 &\lesssim \int_{\Omega_{\varepsilon,T}}
 \big(|\Theta|^2
 + |\psi_\varepsilon\Xi|^2 + |\varepsilon\nabla w_\varepsilon|^2\big)
 + \int_{\Omega_{\varepsilon,T}}
 \big(|\partial_t \Lambda|^2 +|\psi_\varepsilon\partial_t\Xi|^2\big)\\
 &+\int_{\Omega_\varepsilon}\big(|\Lambda(\cdot,T)|^2
 + |\Xi(\cdot,T)|^2\big) =: T_1 + T_2 + T_3.
\end{aligned}
\end{equation}

\begin{equation*}
\left\{\begin{aligned}
&\partial_t I_{33}
= \varepsilon\nabla\psi_\varepsilon\otimes
\big((\partial_t W)^\varepsilon\ast G\big)
+ \varepsilon\nabla\psi_\varepsilon\otimes
\big(W^\varepsilon(\cdot,0)G(\cdot,t)\big)
-\varepsilon\nabla\xi_\varepsilon-\varepsilon\nabla\eta_\varepsilon;\\
&\partial_t I_{42}
= \varepsilon^2\nabla\psi_\varepsilon\otimes
\big((\partial_t\phi)^\varepsilon\ast_2\partial G\big)
+ \varepsilon^2\nabla\psi_\varepsilon\otimes
\big(\phi^\varepsilon(\cdot,0):\partial G(\cdot,t)\big);
\end{aligned}\right.
\end{equation*}

Treating time variable as a parameter,
the idea is totally similar to that given in \cite[pp.22]{Shen20}, and
we provide a proof for reader's convenience. The key ingredient is modifying the value of the effective pressure given in $\eqref{pde1.2}$ as follows
\begin{equation*}
\tilde{p}_{0}(x,t):=
\left\{
\begin{aligned}
&p_{0}(x,t)&\quad&\text{if}\quad x\in\Omega_{\varepsilon},\\
&\Xint-_{\varepsilon(Y_f+z_{k})}p_{0}(\cdot,t)&\quad&\text{if}
\quad x\in\varepsilon(Y_{s}+z_{k}) \quad\text{and}\quad
\varepsilon(Y+z_k)\subset\Omega \text{~for~some~}z_{k}\in \mathbb{Z}^d.
\end{aligned}\right.
\end{equation*}

By definition, it is not hard to derive that, for any $c\in\mathbb{R}$,
\begin{equation}\label{f:6.8}
\int_{0}^{T}\int_{\Omega\setminus\Omega_\varepsilon}
|\tilde{p}_\varepsilon - \tilde{p}_0-c|^2
\leq \frac{|Y_s|}{|Y_f|}\int_{0}^{T}\int_{\Omega_\varepsilon}|p_\varepsilon-p_0-c|^2
\overset{\eqref{pri:1.3}}{\lesssim}\varepsilon
\|f\|_{L^2(0,T;C^{1,1/2}(\bar\Omega))}^2.
\end{equation}
Moreover, by the smoothness of $p_0$ and Poincer\'e's inequality, we can obtain that
\begin{equation}\label{f:6.9}
\int_{0}^{T}
\int_{\Omega\setminus\Omega_\varepsilon}
|\tilde{p}_0 - p_0|^2
\lesssim \varepsilon^2\int_{0}^{T}\int_{\Omega}|\nabla p_0|^2
\overset{\eqref{pri:3.12}}{\lesssim}
\varepsilon^2\|f\|_{L^2(0,T;L^{2}(\Omega))}^2.
\end{equation}

Then, for any $c\in\mathbb{R}$, it is not hard to derive that
\begin{equation*}
\begin{aligned}
\int_{0}^{T}\int_{\Omega}|\tilde{p}_\varepsilon - p_0 - c|^2
&\lesssim \int_{0}^{T}\int_{\Omega}|\tilde{p}_\varepsilon - \tilde{p}_0 - c|^2
+ \int_{0}^{T}\int_{\Omega\setminus\Omega_\varepsilon}|\tilde{p}_0-p_0|^2 \\
&\lesssim
\int_{0}^{T}\int_{\Omega_\varepsilon}|p_\varepsilon - p_0 - c|^2
+ \int_{0}^{T}\int_{\Omega\setminus\Omega_\varepsilon}|\tilde{p}_\varepsilon - \tilde{p}_0-c|^2
+ \int_{0}^{T}\int_{\Omega\setminus\Omega_\varepsilon}|\tilde{p}_0-p_0|^2\\
&\overset{\eqref{pri:1.3},\eqref{f:6.8},\eqref{f:6.9}}{\lesssim}
\varepsilon \|f\|_{L^2(0,T;C^{1,1/2}(\bar\Omega))}^2.
\end{aligned}
\end{equation*}
Consequently, this implies the desired estimate $\eqref{pri:1.4}$ and
we have completed the proof.
\qed

