H\"older's norm by Sobolev norm with respect to the spatial variable,
the results similar to $\eqref{pri:3.1}$ would be established by the
same arguments without any real difficulty, i.e.,
\begin{equation}\label{pri:3.12}
\|p_0\|_{L^q(0,T;H^{m+1}(\Omega))}\leq C
\|f\|_{L^q(0,T;H^{m}(\Omega))},
\qquad m\geq 0,
\end{equation}
where we regard $H^0(\Omega)$ as $L^2(\Omega)$.}

\emph{Concerned with $|\partial_tA|\in L^1(0,T)$, the proof can be found in
\cite[pp.127]{Sandrakov97} based upon Galerkin's methods, while
the stated result relies on the refined estimate $\eqref{pri:3.7}$.}

\label{L3.1}
Assume the same conditions as in Proposition $\ref{P:1}$.
There exists $0<\delta_0\ll 1$, depending on $\|\partial_tA\|_{L^1(0,T)}$, such
that the equation \eqref{pde1.2} possesses
the solution $p_0 \in L^q(0,\delta_0;C^{m+1,\alpha}(\bar{\Omega}))$, satisfying the estimate
\begin{equation}\label{pri:3.2}
\|p_0\|_{L^q(0,\delta_0;C^{m+1,\alpha}(\bar{\Omega}))}\lesssim
\|f\|_{L^q(0,\delta_0;C^{m,\alpha}(\bar{\Omega}))},
\end{equation}
where the multiplicative constant depends on $d$, $|Y_f|$, and $\Omega$.

In view of the divergence-free and boundary conditions of \eqref{pde1.2},
taking t-derivative on its both sides\footnote{To shorten the formula,
we use the notation $A'$ to represent $\partial_t A$ throughout the proof of Lemmas $\ref{L3.1}$
and $\ref{L3.2}$.}, we have
a new form of the equations \eqref{pde1.2}, i.e.,
\begin{equation}\label{rh1}
\left\{
\begin{aligned}
  \nabla\cdot A(0)\nabla p_0(\cdot,t) +
  \nabla\cdot
  \int_{0}^tds
  &A'(t-s)
  \nabla p_0(\cdot,s)
  =
  \nabla\cdot\Big[
  \int_{0}^tdsA'(t-s)f(\cdot,s)+A(0)f(\cdot,t)
  \Big]\quad  \text{in}~\Omega;\\
 \vec{n}\cdot A(0)\nabla p_0(\cdot,t) +
  \vec{n}\cdot
  \int_{0}^tds
  &A'(t-s)\nabla p_0(\cdot,s)
  =
  \vec{n}\cdot\Big[
  \int_{0}^tdsA'(t-s)f(\cdot,s)+A(0) f(\cdot,t)
  \Big]\quad \text{on}~\partial\Omega.
\end{aligned}\right.
\end{equation}
As the argument developed by J.-L. Lions \cite[pp.170]{Lions81}, for a.e. $t>0$, we introduce a function $\hat{p}(\cdot,t)$ as the solution of
\begin{equation}\label{pde:3.1}
\left\{\begin{aligned}
\nabla\cdot\Big[A(0)\nabla\hat{p}(\cdot,t)-\int_{0}^{t}ds
A'(t-s)\nabla p(\cdot,s)
\Big]&=0,&\quad &\text{in}~\Omega;\\
\vec{n}\cdot\Big[A(0)\nabla\hat{p}(\cdot,t)-\int_{0}^{t}ds
A'(t-s)\nabla p(\cdot,s)
\Big]&=0,&\quad &\text{on}~\partial\Omega,\\
\int_{\Omega}\hat{p}(\cdot,t)&=0.
\end{aligned}\right.
\end{equation}
Denote the operator $\nabla\cdot A(0)\nabla =|Y_f|\Delta$
by $\mathcal{L}$, and
\begin{equation}\label{f:3.1}
  K_0(p)(\cdot,t): = \int_{0}^{t}dsA'(t-s)\nabla p(\cdot,s);
  \qquad
  K_1(p): = \mathcal{L}^{-1}\nabla\cdot K_0(p).
\end{equation}
Then, the solution $\hat{p}$ of $\eqref{pde:3.1}$ can be represented by
$\hat{p}(\cdot,t) = K_1(p)(\cdot,t)$ in $\Omega$.
By Schauder estimates (see e.g.
\cite[pp.89]{Giaquinta-Martinazzi12}), there holds that
\begin{equation}\label{pde2.28}
\begin{aligned}
\|\hat{p}(\cdot,t)\|_{C^{2,1/2}(\bar\Omega)}&\leq
C_1
\bigg\|\int_{0}^{t}ds
A'(t-s)\nabla p(\cdot,s)\bigg\|_{C^{1,1/2}(\bar\Omega)}\\
&\leq C_1
\int_{0}^{t}ds
|A'(t-s)|\|\nabla p(\cdot,s)\|_{C^{1,1/2}(\bar\Omega)}
\leq C_1\int_{0}^{t}ds
|A'(t-s)|\| p(\cdot,s)\|_{C^{2,1/2}(\bar\Omega)},
\end{aligned}
\end{equation}
where $C_1$ depends on $|Y_f|$, $d$, and $\Omega$.
In view of $\eqref{f:3.1}$, we observe that $\mathcal{L}K_1(p) =
\nabla\cdot K_0(p)$, and therefore the equations \eqref{rh1} can be rewritten as
\begin{equation*}
\left\{
\begin{aligned}
  \mathcal{L}\Big[p_0(\cdot,t)+K_1(p_0)(\cdot,t)\Big]  &=\nabla\cdot\Big[
  \int_{0}^tdsA'(t-s)f(\cdot,s)+A(0)f(\cdot,t)
  \Big]&\quad &\text{in}~\Omega;\\
 \frac{\partial}{\partial\nu}\Big[p_0(\cdot,t)+K_1(p_0)(\cdot,t)\Big]&=
  \vec{n}\cdot\Big[
  \int_{0}^tdsA'(t-s)f(\cdot,s)+A(0)f(\cdot,t)
  \Big]&\quad &\text{on}~\partial\Omega,
\end{aligned}\right.
\end{equation*}
where the conormal derivative associated with $\mathcal{L}$
is defined by $\partial/\partial\nu:=\vec{n}\cdot A(0)\nabla$.
Similarly, its solution can be expressed by
\begin{equation}\label{rh3}
  \big(p_0+K_1(p_0)\big)(\cdot,t)=\mathcal{L}^{-1}
  \nabla\cdot\Big[
  \int_{0}^tdsA'(t-s)f(\cdot,s)+A(0)f(\cdot,t)
  \Big]=:\tilde{f}_1(\cdot,t).
\end{equation}

Thus, for some $T_1>0$ (which will be fixed later), if constructing the
following map:
\begin{equation}\label{pde:3.2}
 \mathcal{T}_1(p) :=  \tilde{f}_1 - K_1(p)
 \qquad \forall p\in L^q(0,T_1; C^{m+1,\alpha}(\bar\Omega)),
\end{equation}
the unique existence of the solution of $\eqref{rh1}$ in
$L^q(0,T_1; C^{m+1,\alpha}(\bar\Omega))$ is reduced to verifying that the map
$\mathcal{T}_1: L^q(0,T_1; C^{m+1,\alpha}(\bar\Omega))\to L^q(0,T_1; C^{m+1,\alpha}(\bar\Omega))$ is a strict contraction.


To see this, appealing to Schauder estimates again, we firstly derive that
\begin{equation}\label{rh5}
\|\tilde{f}_1(\cdot,t)\|_{C^{m+1,\alpha}(\bar\Omega)}\lesssim
\int_{0}^{t}ds|A'(t-s)|\|f(\cdot,s)\|_{C^{m,\alpha}(\bar\Omega)}
+|A(0)|\|f(\cdot,t)\|_{C^{m,\alpha}(\bar\Omega)}.
\end{equation}
By integrating both sides of $\eqref{pde2.28}$ and $\eqref{rh5}$ with respect to $t$ from
$0$ to $T_1$, Young's inequality, we obtain
\begin{equation}\label{f:3.2}
\begin{aligned}
\|K_1(p)\|_{L^q(0,T_1;C^{m+1,\alpha}(\bar\Omega))}
&\lesssim \|A'\|_{L^1(0,T_1)}
\|p\|_{L^q(0,T_1;C^{m+1,\alpha}(\bar\Omega))};\\
\|\tilde{f}_1\|_{L^q(0,T_1;C^{m+1,\alpha}(\bar\Omega))}
&\lesssim
\|A'\|_{L^1(0,T_1)}
\|f\|_{L^q(0,T_1;C^{m,\alpha}(\bar\Omega))}
  + \|f\|_{L^q(0,T_1;C^{m,\alpha}(\bar\Omega))}.
\end{aligned}
\end{equation}
Then, it follows from the estimates $\eqref{pde:3.2}$ and $\eqref{pde2.28}$ that
\begin{equation*}
\begin{aligned}
\|\mathcal{T}_1(p)(\cdot,t)\|_{C^{m+1,\alpha}(\bar\Omega)}
&\leq \|K_1(p)(\cdot,t)\|_{C^{m+1,\alpha}(\bar\Omega)}+
\|\tilde{f}_1(\cdot,t)\|_{C^{m+1,\alpha}(\bar\Omega)}\\
&\lesssim \int_{0}^{t}ds|A'(t-s)|
\big(\|p(\cdot,s)\|_{C^{m+1,\alpha}(\bar\Omega)}
+\|f(\cdot,s)\|_{C^{m,\alpha}(\bar\Omega)}\big)
+ \|f(\cdot,t)\|_{C^{m,\alpha}(\bar\Omega)},
\end{aligned}
\end{equation*}
and this implies
\begin{equation}\label{rh4}
\begin{aligned}
&\|\mathcal{T}_1(p)\|_{L^q(0,T_1;C^{m+1,\alpha}(\bar\Omega))} \\
&  \lesssim \|A'\|_{L^1(0,T_1)}
  \big(\|p\|_{L^q(0,T_1;C^{m+1,\alpha}(\bar\Omega))}
  +\|f\|_{L^q(0,T_1;C^{m,\alpha}(\bar\Omega))}\big)
  + \|f\|_{L^q(0,T_1;C^{m,\alpha}(\bar\Omega))}.
\end{aligned}
\end{equation}


Also, it is not hard to see that\footnote{By the definition,
the operator
$K_1$ is linear.}
\begin{equation}\label{f:3.6}
 \|\mathcal{T}_1(u)-\mathcal{T}_1(v)
 \|_{L^q(0,T_1;C^{m+1,\alpha}(\bar\Omega))}
 \overset{\eqref{f:3.2}}{\lesssim} \|A'\|_{L^1(0,T_1)}
\|u-v\|_{L^q(0,T_1;C^{m+1,\alpha}(\bar\Omega))}.
\end{equation}
Thus, by Lemma \ref{lemma2.5} we know that $A'\in L^1(0,T)$, and due to the absolute continuity of the integral, for any $\epsilon>0$, there exists $\delta>0$ such that for any interval $I\subset (0,+\infty)$ with $|I|\leq \delta$, we have $\int_{I}|A'|<\epsilon$.
Hence, there exists $\delta_0>0$ such that for $T_1=\delta_0$,
the estimate $\eqref{f:3.6}$ turns to be
\begin{equation*}
\|\mathcal{T}_1(u)-\mathcal{T}_1(v)
 \|_{L^q(0,\delta_0;C^{m+1,\alpha}(\bar\Omega))}
  \leq  \frac{1}{2}\|u-v\|_{L^q(0,\delta_0;C^{m+1,\alpha}(\bar\Omega))}.
\end{equation*}
This coupled with $\eqref{rh4}$ verifies the contraction property of $\mathcal{T}_1$
in $L^q(0,\delta_0;C^{m+1,\alpha}(\bar\Omega))$.


Consequently, it follows from Banach's fixed-point theorem that there exists unique solution $p_0$
such that $\mathcal{T}_1(p_0) = p_0$ in $L^q(0,\delta_0;C^{m+1,\alpha}(\bar\Omega))$, and this together with
the estimate $\eqref{rh4}$ leads to the desired result
\begin{equation*}
\|p_0\|_{L^2(0,\delta_0;C^{2,1/2}(\bar\Omega))}\lesssim
\|f\|_{L^2(0,\delta_0;C^{1,1/2}(\bar\Omega))}.
\end{equation*}
We have completed the proof.

\begin{equation}\label{pde2.28}
\begin{aligned}
\|\hat{p}(\cdot,t)\|_{C^{2,1/2}(\bar\Omega)}&\leq
C_1
\bigg\|\int_{0}^{t}ds
A'(t-s)\nabla p(\cdot,s)\bigg\|_{C^{1,1/2}(\bar\Omega)}\\
&\leq C_1
\int_{0}^{t}ds
|A'(t-s)|\|\nabla p(\cdot,s)\|_{C^{1,1/2}(\bar\Omega)}
\leq C_1\int_{0}^{t}ds
|A'(t-s)|\| p(\cdot,s)\|_{C^{2,1/2}(\bar\Omega)},
\end{aligned}
\end{equation}

\label{L3.2}
Let $0<\delta_0\ll 1$ be given as in Lemma $\ref{L3.1}$. Assume the same
conditions as in Proposition $\ref{P:1}$. Let $n\geq 2$ be an arbitrary fixed  large integer, and $T_k=k \delta_0$
with $k=1,\cdots,n$. Assume that there exists
a unique solution $p_0\in L^q(0,T_{n-1};C^{m+1,\alpha}(\bar\Omega))$ to the equations $\eqref{pde1.2}$,
satisfying the estimate
\begin{equation}\label{pri:3.3}
\|p_0\|_{L^q(0,T_{n-1};C^{m+1,\alpha}(\bar\Omega))}
\leq C_{n-1}
\|f\|_{L^q(0,T_{n-1};C^{m,\alpha}(\bar\Omega))}.
\end{equation}
Then, there exists a unique extension of the solution $p_0\in L^q(0,T_{n};C^{m+1,\alpha}(\bar\Omega))$ to the equations $\eqref{pde1.2}$,
and satisfies the estimate
\begin{equation}\label{pri:3.4}
\|p_0\|_{L^q(0,T_{n};C^{m+1,\alpha}(\bar\Omega))}
\leq C_{n}
\|f\|_{L^q(0,T_{n};C^{m,\alpha}(\bar\Omega))},
\end{equation}
where $C_n$ is monotonically ascending with respect to $n$.

We continue to adopt the notation used in Lemma $\ref{L3.1}$.
For any fixed $n\geq 2$,
and for any $t\in[T_{n-1},T_n]$,  we start from considering
\begin{equation}\label{pde:3.3}
\left\{
\begin{aligned}
  \mathcal{L}\Big[p_0(\cdot,t)+K_n(p_0)(\cdot,t)\Big]
  =\nabla\cdot\Big[&A'\ast f
  +A(0)f
  -\int_{0}^{T_{n-1}}dsA'(t-s)
  \nabla p_0(\cdot,s)
  \Big]\quad\text{in}~\Omega;\\
 \frac{\partial}{\partial\nu}
 \Big[p_0(\cdot,t)+K_n(p_0)(\cdot,t)\Big]
 = \vec{n}\cdot\bigg\{
 &A'\ast f+A(0)f
 -\int_{0}^{T_{n-1}}dsA'(t-s)
  \nabla p_0(\cdot,s)
  \bigg\}\quad\text{on}~\partial\Omega,
\end{aligned}\right.
\end{equation}
where the auxiliary function $K_n(p_0)$ is given by:
\begin{equation*}
\left\{\begin{aligned}
\nabla\cdot\Big[A(0)\nabla K_n(p_0)(\cdot,t)-\int_{T_{n-1}}^{t}ds
A'(t-s)\nabla p_0(\cdot,s)
\Big]&=0 &\quad &\text{in}~\Omega;\\
\vec{n}\cdot\Big[A(0)\nabla K_n(p_0)(\cdot,t)-\int_{T_{n-1}}^{t}ds
A'(t-s)\nabla p_0(\cdot,s)
\Big]&=0 &\quad &\text{on}~\partial\Omega,\\
\int_{\Omega}K_n(p_0)(\cdot,t)&=0.
\end{aligned}\right.
\end{equation*}
In terms of Schauder estimates, we obtain that
\begin{equation*}
\begin{aligned}
\|K_n(p_0)(\cdot,t)\|_{C^{m+1,\alpha}(\bar\Omega)}
\lesssim
\bigg\|\int_{T_{n-1}}^{t}ds
A'(t-s)\nabla p_0(\cdot,s)\bigg\|_{C^{m,\alpha}(\bar\Omega)}
\lesssim
\int_{T_{n-1}}^{t}ds
|A'(t-s)|\|\nabla p_0(\cdot,s)\|_{C^{m,\alpha}(\bar\Omega)}.
\end{aligned}
\end{equation*}
Let $1/q+1/{q'} = 1$. From H\"older's inequality and Fubini's theorem,
it follows that
\begin{equation*}
\begin{aligned}
&\int_{T_{n-1}}^{T_n}\|K_n(p_0)(\cdot,t)
dt\|^q_{C^{m+1,\alpha}(\bar\Omega)}
\lesssim
\int_{T_{n-1}}^{T_n}dt\Big(\int_{T_{n-1}}^{t}ds
|A'(t-s)|\|\nabla p_0(\cdot,s)\|_{C^{m,\alpha}(\bar\Omega)}\Big)^q\\
&\lesssim\int_{T_{n-1}}^{T_n}dt
\bigg(\Big(\int_{T_{n-1}}^{t}ds|A'(t-s)|\Big)^{\frac{q}{q'}}
\int_{T_{n-1}}^{t}ds
|A'(t-s)|\|\nabla p_0(\cdot,s)\|^q_{C^{m,\alpha}(\bar\Omega)}\bigg)\\
&\lesssim \bigg(\int_{0}^{\delta_0}dt|A'(t)|\bigg)^{\frac{q}{q'}+1}
\int_{T_{n-1}}^{T_n}dt\|p_0(\cdot,t)
\|^q_{C^{m+1,\alpha}(\bar\Omega)}.
\end{aligned}
\end{equation*}
This implies that
\begin{equation}\label{f:3.7}
 \|K_n(p_0)
\|_{L^q(T_{n-1},T_n; C^{m+1,\alpha}(\bar\Omega))}
\leq \frac{1}{2} \|p_0
\|_{L^q(T_{n-1},T_n; C^{m+1,\alpha}(\bar\Omega))}.
\end{equation}

\medskip

Then we introduce the following notation for the ease of the statement.
\begin{equation*}
\tilde{f}_n(\cdot,t):=\mathcal{L}^{-1}\nabla\cdot\Big[
\int_{0}^tdsA'(t-s)f(\cdot,s)+A(0)f(\cdot,t)
-\int_{0}^{T_{n-1}}dsA'(t-s)\nabla p_0(\cdot,s)
\Big]\quad \text{in}~\Omega,
\end{equation*}
which would be treated as the known data in the abstract equation below. For a.e. $t\in[T_{n-1},T_n]$, the equations \eqref{pde:3.3} is equivalent to
\begin{equation}\label{pde:3.4}
\big(p_0+K_n(p_0)\big)(\cdot,t)=\tilde{f}_n(\cdot,t)
\quad \text{in}\quad\Omega.
\end{equation}
Thus, the well-posedness of $\eqref{pde:3.3}$ is reduced to studying  the following contraction map\footnote{Similar to the form of $K_1$,
the operator $K_n$ is linear.}:
\begin{equation}\label{f:3.8}
  \mathcal{T}_n(p_0) := \tilde{f}_n - K_n(p_0).
\end{equation}
Obviously, the strict contraction property of $\mathcal{T}_n$  in $L^q(T_{n-1},T_n;C^{m+1,\alpha}(\bar\Omega))$ is due to the estimate
$\eqref{f:3.7}$.

\medskip

We continue to verify that the range of $\mathcal{T}_n$ is included in $L^q(T_{n-1},T_n;C^{m+1,\alpha}(\bar\Omega))$, and start from
\begin{equation*}
\|\mathcal{T}_n(p_0)(\cdot,t)\|_{C^{m+1,\alpha}(\bar\Omega)}
\leq \|K_n(p_0)(\cdot,t)\|_{C^{m+1,\alpha}(\bar\Omega)}+
\|\tilde{f}_n(\cdot,t)\|_{C^{m+1,\alpha}(\bar\Omega)}.
\end{equation*}
On account of the estimate $\eqref{f:3.7}$, it suffices to estimate
the quantity $\|\tilde{f}_n\|_{L^q(T_{n-1},T_n;C^{m+1,\alpha}(\bar\Omega))}$.
According to the definition of $\tilde{f}_n$ above,
by using Schauder estimates, we first have
\begin{equation*}
\begin{aligned}
&\|\tilde{f}_n(\cdot,t)\|_{C^{m+1,\alpha}(\bar\Omega)}\\
&\lesssim
\int_{0}^{t}ds|A'(t-s)|
\|f(\cdot,s)\|_{C^{m,\alpha}(\bar\Omega)}
+|A(0)|\|f(\cdot,t)\|_{C^{m,\alpha}(\bar\Omega)}
+\int_{0}^{T_{n-1}}ds|A'(t-s)|
\|\nabla p_0(\cdot,s)\|_{C^{m,\alpha}(\bar\Omega)},
\end{aligned}
\end{equation*}
and then appealing to H\"older's inequality and Fubini's theorem, as well as, the inductive assumption, we obtain
\begin{equation*}\label{rh11}
\begin{aligned}
&\int_{T_{n-1}}^{T_n}dt\|\tilde{f}_n(\cdot,t)
\|^q_{C^{m+1,\alpha}(\bar\Omega)} \\









&\lesssim\bigg(
\int_{0}^{T_n}dt|A'(t)|\bigg)^{\frac{q}{q'}+1}
\bigg(\int_{0}^{T_n}dt\|f(\cdot,t)
\|^q_{C^{m,\alpha}(\bar\Omega)}
+\int_{0}^{T_{n-1}}dt\|p_0(\cdot,t)\|^q_{C^{m+1,\alpha}(\bar\Omega)}\bigg)
+\int_{0}^{T_n}dt\|f(\cdot,t)
\|^q_{C^{m,\alpha}(\bar\Omega)}\\
&\overset{\eqref{pri:3.3}}{\lesssim}\int_{0}^{T_n}dt\|f(\cdot,t)
\|^q_{C^{m,\alpha}(\bar\Omega)}.
\end{aligned}
\end{equation*}
This coupled with $\eqref{f:3.8}$ leads to
\begin{equation*}
\begin{aligned}
\|\mathcal{T}_n(p_0)\|_{L^q(T_{n-1},T_n;C^{m+1,\alpha}(\bar\Omega))}
&\leq \|K_n(p_0)\|_{L^q(T_{n-1},T_n; C^{m+1,\alpha}(\bar\Omega))}
+\|\tilde{f}_n\|_{L^q(T_{n-1},T_n; C^{m+1,\alpha}(\bar\Omega))}\\
&\overset{\eqref{f:3.7}}{\leq} \frac{1}{2}\|p_0\|_{L^q(T_{n-1},T_n; C^{m+1,\alpha}(\bar\Omega))}
+ C\|f\|_{L^q(0,T_n; C^{m,\alpha}(\bar\Omega))}.
\end{aligned}
\end{equation*}

\medskip

Hence, by Banach's fixed-point theorem, there exists the unique solution
$p_0\in L^q(T_{n-1},T_n;C^{m+1,\alpha}(\bar\Omega))$, satisfying the equation
$\eqref{pde:3.4}$.  Moreover, we have
\begin{equation*}
\begin{aligned}
\|p_0\|_{L^q(T_{n-1},T_n;C^{m+1,\alpha}(\bar\Omega))}
\leq
\frac{1}{2}\|p_0\|_{L^q(T_{n-1},T_n; C^{m+1,\alpha}(\bar\Omega))}
+ C\|f\|_{L^q(0,T_n; C^{m,\alpha}(\bar\Omega))},
\end{aligned}
\end{equation*}
which further implies
\begin{equation*}
\|p_0\|_{L^q(T_{n-1},T_n;C^{m+1,\alpha}(\bar\Omega))}
\lesssim
\|f\|_{L^q(0,T_{n};C^{m,\alpha}(\bar\Omega))}.
\end{equation*}
As a result, it follows from \eqref{pri:3.3} that
\begin{equation*}
\|p_0\|_{L^q(0,T_n;C^{m+1,\alpha}(\bar\Omega))}
\lesssim
\|f\|_{L^q(0,T_n;C^{m,\alpha}(\bar\Omega))},
\end{equation*}
and this completes the whole proof.
